select count(*) from sxz_disease_auto_task
where del_flag = '0' and camera_task_id = #{cameraTaskId} and model_id = #{modelId}
  and task_id != #{taskId}

select r.id source_image_id, r.url image_url, #{task.modelId} model_id_snapshot,
       coalesce(r.capture_time, r.create_time) capture_time
from image_record r
where r.url is not null and trim(r.url) != ''
  and (
      r.task_id = #{task.cameraTaskId}
      or (
          r.device_id = #{task.deviceId}
          and not exists (
              select 1 from image_record exact_image
              where exact_image.task_id = #{task.cameraTaskId}
                and exact_image.url is not null and trim(exact_image.url) != ''
          )
      )
  )
order by case when r.task_id = #{task.cameraTaskId} then 0 else 1 end,
         coalesce(r.capture_time, r.create_time) desc, r.id desc
limit 1



    r.record_type = '病虫害' and r.record_mode = '自动定时'
    and r.create_time >= date_sub(now(), interval #{days} day)
    and r.create_time >= #{beginTime}
    and r.create_time <= #{endTime}
    and r.park_id = #{parkId}
    and r.device_id = #{deviceId}
    and r.model_id = #{modelId}
    and i.task_id = #{taskId}
    and d.disease_name like concat('%', #{diseaseName}, '%')
    and trim(d.disease_name) in ('健康','健康叶片')
    and trim(d.disease_name) not in ('健康','健康叶片')

order by r.create_time desc, i.item_id desc
